<script setup lang="ts">
import ActionIcon from '../components/ActionIcon.vue';
import { computed, onUnmounted, ref, watch } from 'vue';
import { useDispatchStore } from '../stores/dispatch';
import { taskStepName } from '../task-step-labels';
const store=useDispatchStore();
const parameters=ref<any>(null),bindings=ref<any>(null),message=ref(''),busy=ref(false),validation=ref<any>(null),inspection=ref<any>(null);
let epoch=0;const loadedContext=ref("");
onUnmounted(()=>{++epoch;});
const context=computed(()=>[store.demoMode,store.adapterIdentity?.sha256,store.snapshot?.map?.id,store.snapshot?.map?.version,store.snapshot?.map?.definitionHash].join("|"));
const editable=computed(()=>store.fresh&&!store.demoMode&&loadedContext.value===context.value);
watch(()=>[context.value,store.fresh],()=>{++epoch;validation.value=null;inspection.value=null;busy.value=false;loadedContext.value="";message.value="后台上下文或连接已变化；编辑内容保留，需重新读取后校验。";});
async function run(fn:(mine:number)=>Promise<void>){if(store.demoMode||!store.fresh)return;const mine=++epoch;busy.value=true;message.value='';try{await fn(mine);}catch(e){if(mine===epoch)message.value=String(e);}finally{if(mine===epoch)busy.value=false;}}
async function load(){await run(async n=>{const p=await store.api('/api/task-parameters');const b=await store.api('/api/map-bindings');if(n===epoch){parameters.value=p;bindings.value=b;loadedContext.value=context.value;validation.value=null;inspection.value=null;}});}
function request(){return{requestId:crypto.randomUUID().replaceAll('-',''),expectedRevision:parameters.value.revision,mapId:parameters.value.mapId,mapVersionId:parameters.value.mapVersionId,configuration:JSON.parse(JSON.stringify(parameters.value.configuration))};}
async function validate(save=false){if(!editable.value)return;await run(async n=>{const result:any=await store.api('/api/task-parameters/'+(save?'save':'validate'),request());if(n!==epoch)return;validation.value=result;message.value=result.message;if(save&&result.accepted&&result.snapshot)parameters.value=result.snapshot;});}
async function saveBindings(){if(!editable.value)return;await run(async n=>{const b=await store.api('/api/map-bindings',{expectedRevision:bindings.value.revision,bindings:bindings.value.bindings});if(n===epoch){bindings.value=b;message.value='绑定已保存；按后台提示受控重启后生效，不代表现场坐标已验证。';inspection.value=null;}});}
async function inspect(vehicleId:string){await run(async n=>{const x=await store.api('/api/map-bindings/inspect',{vehicleId});if(n===epoch)inspection.value=x;});}
function addBinding(){bindings.value.bindings.push({vehicleId:'',localMapId:'',localMapVersion:'',robotMap:'',robotMapMd5:'',confirmationNote:'',coordinatesVerified:false});}
</script>
<template>
<section class="management-page engineering-settings"><header class="management-title"><h2>任务参数与厂家地图绑定</h2><button :disabled="busy||store.demoMode||!store.fresh" @click="load"><ActionIcon name="refresh"/>读取后台配置</button></header>
<p>配置保存不启动设备。绑定保存保留PLC、车辆和全局开关；revision冲突必须重读。坐标确认只能依据实际核对资料，不能从名称或相似图形推断。</p>
<p v-if="store.demoMode||!store.fresh" class="inline-warning">请退出演示并连接后台后读取配置。</p><p role="status">{{message}}</p>
<fieldset v-if="parameters" :disabled="busy||!editable"><legend>九步任务参数</legend><p>地图 {{parameters.mapId||'未激活'}} / {{parameters.mapVersionId||'无版本'}} · 修订 {{parameters.revision}}</p><p>{{parameters.explanation}}</p>
<p v-if="parameters.configuration.engineeringSource">已绑定工程 {{parameters.configuration.engineeringSource.versionId}}。车辆池随每条工位映射保留；新增或调整工位及车辆池请到<RouterLink to="/engineering">工程配置中心</RouterLink>发布后重新应用。此页可调整保留的车辆动作和超时。</p>
<fieldset :disabled="!!parameters.configuration.engineeringSource"><legend>工程站点绑定</legend><div class="creation-grid"><label>倒料PLC工位<input v-model="parameters.configuration.dumperStationId"/></label><label>等待点<input v-model="parameters.configuration.waitingSite"/></label><label>倒料点<input v-model="parameters.configuration.dumpingSite"/></label></div>
<h3>取货工位与业务站点</h3><div v-for="(p,i) in parameters.configuration.pickups" :key="i" class="settings-row"><label>PLC工位<input v-model="p.stationId"/></label><label>业务取货点<input v-model="p.pickupSite"/></label><button @click="parameters.configuration.pickups.splice(i,1)"><ActionIcon name="remove"/>移除此行</button></div><button @click="parameters.configuration.pickups.push({stationId:'',pickupSite:''})"><ActionIcon name="add"/>新增取货映射</button>
<h3>已配置待机位</h3><p v-for="s in parameters.configuration.standbys??[]" :key="s.id">{{s.id}} → {{s.site}} · 车辆池 {{s.vehiclePoolId}} · 适用车辆 {{s.allowedVehicleIds.join('、')}}</p><p>待机位在工程配置中心统一维护，随工程版本应用。运行页面按当前车辆过滤可选待机位。</p>
</fieldset><h3>四段末站车辆动作</h3><div v-for="a in parameters.configuration.actions" :key="a.stepType" class="settings-row"><b>{{taskStepName(a.stepType)}}</b><label>动作<input v-model="a.operation" placeholder="使用厂家已核定动作"/></label><label>顶升高度（留空不指定）<input v-model.number="a.jackHeight" type="number" @change="a.jackHeight=a.jackHeight===''?null:a.jackHeight"/></label><label v-for="key in ['recognize','usePgv','useDownPgv']" :key="key">{{({recognize:'识别',usePgv:'使用PGV',useDownPgv:'使用下视PGV'} as Record<string,string>)[key]}}<select v-model="a[key]"><option :value="null">未指定</option><option :value="true">是</option><option :value="false">否</option></select></label></div>
<h3>步骤超时提示（秒，0关闭）</h3><div class="creation-grid"><label v-for="t in parameters.configuration.stepTimeouts" :key="t.stepType">{{taskStepName(t.stepType)}}<input v-model.number="t.seconds" type="number" min="0"/></label></div>
<button :disabled="!parameters.mapId" @click="validate()"><ActionIcon name="check"/>逐步校验</button><button :disabled="!parameters.canSave||!parameters.mapId" @click="validate(true)"><ActionIcon name="save"/>校验并保存任务参数</button>
<div v-if="validation"><h3>后台逐步校验结果</h3><p v-for="(row,i) in validation.steps" :key="i">{{row.stationId}} · {{row.step.sequence}} {{row.step.name}}：{{row.step.validationErrors?.join('；')||'配置检查通过（不是现场动作通过）'}}</p></div></fieldset>
<fieldset v-if="bindings" :disabled="busy||!editable"><legend>厂家地图及坐标绑定</legend><p>修订 {{bindings.revision}} · {{bindings.restartRequired?'存在待重启配置':'无待重启更改'}}</p>
<div v-for="(b,i) in bindings.bindings" :key="i" class="binding-card"><div class="creation-grid"><label v-for="(label,key) in {vehicleId:'车辆编号',localMapId:'本地地图ID',localMapVersion:'本地版本ID',robotMap:'厂家地图名',robotMapMd5:'厂家确认MD5',confirmationNote:'坐标与地图核对依据'}" :key="key">{{label}}<input v-model="b[key]"/></label></div><label><input v-model="b.coordinatesVerified" type="checkbox"/>已按实际资料完成坐标核对（人工声明）</label><button @click="inspect(b.vehicleId)"><ActionIcon name="search"/>只读查询车端版本／站点</button><button @click="bindings.bindings.splice(i,1)"><ActionIcon name="remove"/>移除此绑定稿</button></div>
<button @click="addBinding"><ActionIcon name="add"/>新增绑定</button><button :disabled="!bindings.canManage" @click="saveBindings"><ActionIcon name="save"/>保存绑定配置</button><div v-if="inspection"><p>{{inspection.reason}} · {{inspection.robokitVersion}} · {{inspection.robotMap}} · {{inspection.robotMapMd5}}</p><p v-for="x in inspection.issues" :key="x">{{x}}</p><details><summary>站点与映射（只读观察）</summary><p v-for="x in inspection.mappings" :key="x.nodeId">业务 {{x.nodeId}} → 厂家 {{x.siteId}}：{{x.reason}}</p></details></div></fieldset>
</section></template>
<style scoped>.engineering-settings p{font-size:13px;line-height:1.8}.engineering-settings fieldset{border:1px solid #2c4563;padding:18px;margin:20px 0;min-width:0}.engineering-settings legend,.engineering-settings h3{color:#a9c9e5;margin:15px 0}.settings-row{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:12px 0}.settings-row label{font-size:12px;display:grid;gap:5px}.settings-row input{max-width:200px}.binding-card{border-bottom:1px solid #2c4563;padding:16px 0}button{margin:6px}</style>
